#!/usr/bin/env node
// Scans assets/audio_fr and assets/audio_en for "<lessonId>.mp3" (+ optional "<lessonId>.json" word timings)
// and generates src/content/generated/audioIndex.ts with static require() calls (Metro needs static paths).
import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const OUT = path.join(ROOT, 'src', 'content', 'generated');
fs.mkdirSync(OUT, { recursive: true });

const langs = ['fr', 'en'];
const lines = [
  '// AUTO-GENERATED by scripts/build-audio-index.mjs - do not edit.',
  'export type AudioEntry = { audio: number; timing?: unknown };',
  'export const audioIndex: Record<"fr" | "en", Record<number, AudioEntry>> = {',
];
const report = [];
for (const lang of langs) {
  const dir = path.join(ROOT, 'assets', `audio_${lang}`);
  const entries = [];
  if (fs.existsSync(dir)) {
    const ids = fs.readdirSync(dir).map((f) => /^(\d+)\.mp3$/.exec(f)).filter(Boolean).map((m) => Number(m[1])).sort((a, b) => a - b);
    for (const id of ids) {
      const base = `../../../assets/audio_${lang}/${id}`;
      const hasJson = fs.existsSync(path.join(dir, `${id}.json`));
      entries.push(`    ${id}: { audio: require('${base}.mp3')${hasJson ? `, timing: require('${base}.json')` : ''} },`);
    }
  }
  report.push(`${lang}=${entries.length}`);
  lines.push(`  ${lang}: {`, ...entries, '  },');
}
lines.push('};', '');
fs.writeFileSync(path.join(OUT, 'audioIndex.ts'), lines.join('\n'));
console.log(`[build-audio-index] ${report.join(' ')}`);
